// Joins the PJSR sources into build/pjsr/mcp-handlers.js, the one file each driver script
// includes. Function declarations are hoisted and no top level variable depends on another
// file, so the order is for reading only.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = path.join(repoRoot, "build", "pjsr", "mcp-handlers.js");

const PJSR_SOURCES = [
  "pjsr/core.js",
  "pjsr/images.js",
  "pjsr/processes.js",
  "pjsr/history.js",
  "pjsr/dispatch.js",
];

const lines = ["// Generated by scripts/build-pjsr-bundle.mjs from the files in pjsr/. Do not edit.", ""];
for (const source of PJSR_SOURCES) {
  lines.push(`// ---- ${source} ----`);
  lines.push(...fs.readFileSync(path.join(repoRoot, source), "utf8").split(/\r?\n/), "");
}

fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, lines.join("\n"), "utf8");
console.log(`wrote ${path.relative(repoRoot, outputPath)} (${lines.length} lines)`);
